def f(I):
    H=len(I); W=len(I[0])
    O=[row[:] for row in I]
    for v in set(x for row in I for x in row)-{max(set(x for row in I for x in row), key=lambda z: sum(row.count(z) for row in I))}:
        # background = most common color
        pass
    bg=max(set(x for row in I for x in row), key=lambda z: sum(row.count(z) for row in I))
    for comp in [c for cs in comps(I,v) for c in [cs]]:
        if len(comp)!=3: continue
        # elbow: find corner = cell with both orthogonal neighbors in comp
        corner=None; dirs=[]
        for (r,c) in comp:
            nb=[(a,b) for a,b in comp if abs(a-r)+abs(b-c)==1]
            if len(nb)==2 and any((abs(a-b)+abs(c-d))==0 for a,b in [(r,c)]) : pass
        ok=False
        for (r,c) in comp:
            n1=(r+1,c); n2=(r-1,c); n3=(r,c+1); n4=(r,c-1)
            inside=[p for p in (n1,n2,n3,n4) if p in comp]
            if len(inside)==2:
                corner=(r,c); dirs=[p-(r,c) for p in inside]
                ok=True; break
        if not ok: continue
        # bisector direction: normalize sum normalized
        s=(dirs[0][0]+dirs[1][0], dirs[0][1]+dirs[1][1])
        import math
        s=(s[0]//math.gcd(abs(s[0]),abs(s[1])), s[1]//math.gcd(abs(s[0]),abs(s[1])))
        start=(corner[0]+2*s[0], corner[1]+2*s[1])
        # walk until edge or non-bg cell
        r,c=start
        while 0<=r<H and 0<=c<W:
            if I[r][c]!=bg: break
            O[r][c]=v
            r+=s[0]; c+=s[1]
    return O

